package android.text;
public class PrecomputedText implements Spannable {
    private final SpannableString data; private final Params params;
    private PrecomputedText(CharSequence text,Params params){data=new SpannableString(text);this.params=params;}
    public static PrecomputedText create(CharSequence text,Params params){return new PrecomputedText(text,params);} public Params getParams(){return params;}
    public int length(){return data.length();} public char charAt(int i){return data.charAt(i);} public CharSequence subSequence(int start,int end){return data.subSequence(start,end);} public String toString(){return data.toString();} public void setSpan(Object what,int start,int end,int flags){data.setSpan(what,start,end,flags);} public void removeSpan(Object what){data.removeSpan(what);} public <T>T[] getSpans(int start,int end,Class<T> type){return data.getSpans(start,end,type);} public int getSpanStart(Object o){return data.getSpanStart(o);} public int getSpanEnd(Object o){return data.getSpanEnd(o);} public int getSpanFlags(Object o){return data.getSpanFlags(o);} public int nextSpanTransition(int start,int limit,Class type){return data.nextSpanTransition(start,limit,type);}
    public static final class Params { private final TextPaint paint; private final TextDirectionHeuristic direction; private final int strategy,hyphenation; private Params(TextPaint p,TextDirectionHeuristic d,int s,int h){paint=p;direction=d;strategy=s;hyphenation=h;} public TextPaint getTextPaint(){return paint;} public TextDirectionHeuristic getTextDirection(){return direction;} public int getBreakStrategy(){return strategy;} public int getHyphenationFrequency(){return hyphenation;}
        public static final class Builder { private final TextPaint paint; private TextDirectionHeuristic direction=TextDirectionHeuristics.FIRSTSTRONG_LTR; private int strategy,hyphenation; public Builder(TextPaint paint){this.paint=paint;} public Builder setTextDirection(TextDirectionHeuristic d){direction=d;return this;} public Builder setBreakStrategy(int s){strategy=s;return this;} public Builder setHyphenationFrequency(int h){hyphenation=h;return this;} public Params build(){return new Params(paint,direction,strategy,hyphenation);} }
    }
}
